#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

int main() {
	// your code goes here
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	
	int t;
	cin>>t;
	
	while(t--){
	    int n ;
	    cin>>n;
	    
	    
	    int sz = 3*n;
	    
	    vector<ll> a(sz);
	    
	    for(auto& x:a) cin>> x;
	    
	    sort(a.rbegin(),a.rend());
	    
	    vector<ll> pref(sz+1);
	    
	    for(int i=0;i<sz;i++) pref[i+1] = pref[i] + a[i];
	    
	    ll ans = 0;
	    
	    for(int total=0;total<=n;total++){
	        int lo = 0,hi=total-1;
	        int take = 0;
	        
	        while(lo<=hi){
	            int mid = lo+(hi-lo)/2;
	            
	            ll gain = 2LL*a[mid];
	            
	            ll loss = a[2*total-mid-1] + 3LL*a[sz-total-mid-1];
	            
	            if(gain>=loss){
	                take = mid+1;
	                lo = mid+1;
	            }
	            else{
	                hi = mid-1;
	            }
	            
	        }
	        
	        long long cur = 2LL*pref[take] + pref[2*total-take] + 3LL*pref[sz-total-take];
	        ans = max(ans,cur);
	        
	    }
	    
	    cout<<ans<<'\n';
	    
	}
	
	return 0;

}
